def outer():
    value = 0
    def inner():
        nonlocal value
        value += 1
    return inner

async def fetch(url: str, /, *, timeout: float = 1.0) -> bytes:
    async with client(url) as response:
        return await response.read(timeout=timeout)

@outer
@decorate(flag=True)
class Example(Base, metaclass=Meta):
    """class doc"""
    @classmethod
    @property
    def item(cls):
        return cls.value

try:
    run()
except (ValueError, TypeError) as error:
    recover(error)
else:
    finish()
finally:
    close()

