try:
    run()
except* ValueError as error:
    recover(error)
except* TypeError:
    report()

for item in items:
    if item is None:
        continue
    else:
        consume(item)
else:
    finish()

class Box[T: object](object):
    def __init__(self, value: T) -> None:
        self.value = value
